#include <cstddef>
#include <utility>

class Image
{
public:
    Image(int width, int height)
        : m_width{ width }, m_height{ height }, m_pixels{ new unsigned char[static_cast<std::size_t>(width) * static_cast<std::size_t>(height)]{} }
    {
    }

    ~Image() { delete[] m_pixels; }

    Image(const Image& other) : Image{ other.m_width, other.m_height }
    {
        const std::size_t count{ static_cast<std::size_t>(m_width) * static_cast<std::size_t>(m_height) };
        for (std::size_t i{ 0 }; i < count; ++i) m_pixels[i] = other.m_pixels[i];
    }

    Image(Image&& other) noexcept
        : m_width{ std::exchange(other.m_width, 0) }, m_height{ std::exchange(other.m_height, 0) }, m_pixels{ std::exchange(other.m_pixels, nullptr) }
    {
    }

    Image& operator=(const Image& other)
    {
        if (this != &other)
        {
            Image copy{ other };
            swap(copy);
        }
        return *this;
    }

    Image& operator=(Image&& other) noexcept
    {
        if (this != &other)
        {
            delete[] m_pixels;
            m_width = std::exchange(other.m_width, 0);
            m_height = std::exchange(other.m_height, 0);
            m_pixels = std::exchange(other.m_pixels, nullptr);
        }
        return *this;
    }

    int width() const { return m_width; }
    int height() const { return m_height; }
    unsigned char& at(int x, int y) { return m_pixels[static_cast<std::size_t>(y) * static_cast<std::size_t>(m_width) + static_cast<std::size_t>(x)]; }
    const unsigned char& at(int x, int y) const { return m_pixels[static_cast<std::size_t>(y) * static_cast<std::size_t>(m_width) + static_cast<std::size_t>(x)]; }
    const unsigned char* pixels() const { return m_pixels; }

private:
    void swap(Image& other) noexcept
    {
        std::swap(m_width, other.m_width);
        std::swap(m_height, other.m_height);
        std::swap(m_pixels, other.m_pixels);
    }

    int m_width{ 0 };
    int m_height{ 0 };
    unsigned char* m_pixels{ nullptr };
};

unitTests:
static_assert(std::is_nothrow_move_constructible_v<Image> && std::is_nothrow_move_assignable_v<Image>, "the move operations should be noexcept");

TEST("starts black with the right size") { const Image img{ 4, 3 }; CHECK_EQ(img.width(), 4); CHECK_EQ(img.height(), 3); CHECK_EQ(img.at(3, 2), 0); }
TEST("pixels are stored row by row") { Image img{ 4, 3 }; img.at(1, 2) = 200; CHECK_EQ(img.pixels()[2 * 4 + 1], 200); }
TEST("copies are deep") { Image a{ 2, 2 }; a.at(0, 0) = 7; Image b{ a }; b.at(0, 0) = 9; CHECK_EQ(a.at(0, 0), 7); Image c{ 1, 1 }; c = a; CHECK_EQ(c.width(), 2); CHECK_EQ(c.at(0, 0), 7); CHECK(c.pixels() != a.pixels()); }
TEST("moves steal the pixels") { Image a{ 8, 8 }; const unsigned char* p{ a.pixels() }; Image b{ std::move(a) }; CHECK(b.pixels() == p); CHECK(a.pixels() == nullptr); CHECK_EQ(a.width(), 0); CHECK_EQ(a.height(), 0); Image c{ 1, 1 }; c = std::move(b); CHECK(c.pixels() == p); CHECK(b.pixels() == nullptr); }
TEST("no leaks") { CHECK_NO_LEAK(Image a{ 16, 16 }; Image b{ a }; Image c{ std::move(a) }; b = c; c = Image{ 2, 2 }; b = std::move(c)); }

